test("isLogFactoryMatched()", async () => {
  const { address } = await deployFactory({ sender: ALICE });
  const blockData = await createPair({
    factory: address,
    sender: ALICE,
  });

  const { eventCallbacks } = getPairWithFactoryIndexingBuild({
